    const m = modal({ title: `Import into ${proj?.name || 'project'}`, sub: 'Files stay in this project and show up in its language chart and file browser. Secrets (.env, keys), node_modules and binaries are skipped automatically.', width: 600,
      body: `<div class="hc-tabs"><button data-t="files" class="${opts.tab !== 'github' ? 'on' : ''}">Files, folder or zip</button><button data-t="github" class="${opts.tab === 'github' ? 'on' : ''}">From GitHub</button></div>
        <div data-p="files"><div class="dropzone" id="dz"><div style="font-size:28px">⇪</div><p style="margin:6px 0 12px">Drag files, a folder or a .zip here</p><div class="btn-row" style="justify-content:center"><button class="outline-button btn-sm" id="pickFiles">Choose files</button><button class="outline-button btn-sm" id="pickDir">Choose folder</button><button class="outline-button btn-sm" id="pickZip">Choose .zip</button></div><input type="file" id="inFiles" multiple hidden><input type="file" id="inDir" webkitdirectory multiple hidden><input type="file" id="inZip" accept=".zip,application/zip" hidden></div><div id="picked" class="muted small" style="margin:10px 0"></div></div>
        <div data-p="github" hidden><label class="hc-field">Repository<input class="inp" id="ghRepo" placeholder="owner/repo or https://github.com/owner/repo" value="${esc(opts.repo || '')}"></label><label class="hc-field">Branch <span class="muted">(optional, defaults to the main branch)</span><input class="inp" id="ghBranch" placeholder="main"></label><small class="muted">Public repositories work right away. For private repositories connect GitHub first (Connections button).</small></div>
        <label class="hc-field" style="display:flex;gap:8px;align-items:center;margin-top:12px"><input type="checkbox" id="impOver"> Replace files that already exist</label>
        <div id="impProg" hidden><div class="progress"><i id="impBar"></i></div><p class="muted small" id="impTxt" style="margin:6px 0 0"></p></div><div id="impReport"></div>`,
      actions: [{ label: 'Close' }, { label: 'Import', kind: 'primary', id: 'go', keepOpen: true, onClick: () => run() }] });
    const tab = () => $('.hc-tabs button.on', m.el).dataset.t; const setTab = t => { $$('.hc-tabs button', m.el).forEach(b => b.classList.toggle('on', b.dataset.t === t)); $$('[data-p]', m.el).forEach(p => { p.hidden = p.dataset.p !== t; }); }; $$('.hc-tabs button', m.el).forEach(b => b.addEventListener('click', () => setTab(b.dataset.t))); setTab(opts.tab === 'github' ? 'github' : 'files');
    const summary = () => { $('#picked', m.el).textContent = picked.length ? `${picked.length} item${picked.length === 1 ? '' : 's'} ready: ${picked.slice(0, 3).map(f => f._path || f.webkitRelativePath || f.name).join(', ')}${picked.length > 3 ? '…' : ''}` : ''; };
    const addFiles = (list) => { picked = [...picked, ...list]; summary(); }; const dz = m.$('#dz');
    m.$('#pickFiles').addEventListener('click', () => m.$('#inFiles').click()); m.$('#pickDir').addEventListener('click', () => m.$('#inDir').click()); m.$('#pickZip').addEventListener('click', () => m.$('#inZip').click());
    for (const id of ['#inFiles', '#inDir', '#inZip']) m.$(id).addEventListener('change', e => { addFiles([...e.target.files]); e.target.value = ''; });
    dz.addEventListener('dragover', e => { e.preventDefault(); dz.classList.add('over'); }); dz.addEventListener('dragleave', () => dz.classList.remove('over')); dz.addEventListener('drop', async e => { e.preventDefault(); dz.classList.remove('over'); addFiles(await entriesFromDataTransfer(e.dataTransfer)); });
